public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || start.length == 0 || end == null || end.length == 0) {
        return "cannot be travelled";
    }
    int startNode = start[0];
    int endNode = end[0];
    java.util.Map<Integer, java.util.List<Integer>> graph = new java.util.HashMap<>();
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) {
            continue;
        }
        int u = edge[0];
        int v = edge[1];
        graph.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(v);
        graph.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(u);
    }
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.add(startNode);
    visited.add(startNode);
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current == endNode) {
            return "can be travelled";
        }
        java.util.List<Integer> neighbors = graph.get(current);
        if (neighbors == null) {
            continue;
        }
        for (int neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (Arrays.equals(start, end)) return "can be travelled";
    // Build graph adjacency list
    Map<String, List<String>> graph = new HashMap<>();
    for (int[] p : paths) {
        if (p.length < 2 * n) continue; // invalid path entry, skip
        // Extract first n elements as from, next n as to
        StringBuilder sbFrom = new StringBuilder();
        StringBuilder sbTo = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sbFrom.append(p[i]).append(",");
        }
        for (int i = n; i < 2 * n; i++) {
            sbTo.append(p[i]).append(",");
        }
        // Remove trailing comma
        sbFrom.setLength(sbFrom.length() - 1);
        sbTo.setLength(sbTo.length() - 1);
        String from = sbFrom.toString();
        String to = sbTo.toString();
        graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
        graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from); // assume undirected
    }
    // Convert start and end to keys
    StringBuilder sbStart = new StringBuilder();
    StringBuilder sbEnd = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sbStart.append(start[i]).append(",");
        sbEnd.append(end[i]).append(",");
    }
    sbStart.setLength(sbStart.length() - 1);
    sbEnd.setLength(sbEnd.length() - 1);
    String startKey = sbStart.toString();
    String endKey = sbEnd.toString();
    // BFS to find path
    Set<String> visited = new HashSet<>();
    Queue<String> queue = new LinkedList<>();
    queue.offer(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String curr = queue.poll();
        if (curr.equals(endKey)) return "can be travelled";
        List<String> neighbors = graph.getOrDefault(curr, Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

