        String current = queue.poll();
        for (String neighbor : graph.getOrDefault(current, java.util.Collections.emptySet())) {
            if (visited.add(neighbor)) {
                if (neighbor.equals(endKey)) {
                    return "can be travelled";
                }
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build a set of allowed coordinates from the given paths
    java.util.Set<String> allowed = new java.util.HashSet<>();
    for (int[] p : paths) {
        if (p.length >= 2) {
            allowed.add(p[0] + "," + p[1]);
        }
    }
    // Check if both start and end are in the allowed set
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (!allowed.contains(startKey) || !allowed.contains(endKey)) {
        return "cannot be travelled";
    }
    // BFS to determine reachability
    boolean[][] visited = new boolean[n][n];
    java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
    queue.offer(new int[]{start[0], start[1]});
    visited[start[0]][start[1]] = true;
    int[] dir = {0, 1, 0, -1, 0};
    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        if (cur[0] == end[0] && cur[1] == end[1]) {
            return "can be travelled";
        }
        for (int i = 0; i < 4; i++) {
            int nx = cur[0] + dir[i];
            int ny = cur[1] + dir[i + 1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                String key = nx + "," + ny;
                if (allowed.contains(key)) {
                    visited[nx][ny] = true;
                    queue.offer(new int[]{nx, ny});
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length < 4) continue;
        String a = p[0] + "," + p[1];
        String b = p[2] + "," + p[3];
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    adj.computeIfAbsent(startKey, k -> new java.util.ArrayList<>());
    adj.computeIfAbsent(endKey, k -> new java.util.ArrayList<>());
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) return "can be travelled";
        java.util.List<String> neighbors = adj.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split("\\s+");
    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    String[] monthNames = {
        "January","February","March","April","May","June",
        "July","August","September","October","November","December"
    };
    String monthName = (month >= 1 && month <= 12) ? monthNames[month - 1] : "Invalid";

    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setLenient(false);
    cal.set(year, month - 1, day);
    int dayOfWeekIndex = cal.get(java.util.Calendar.DAY_OF_WEEK); // 1=Sunday

    String[] weekdays = {
        "Sunday","Monday","Tuesday","Wednesday",
        "Thursday","Friday","Saturday"
    };
    String weekday = weekdays[dayOfWeekIndex - 1];

    return monthName + " " + day + ", " + year + " is a " + weekday;
}

