public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    double mean = sum / (double) (n - 2 * k);
    return mean;
}

