public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        freq[num % k]++;
    }
    if (freq[0] % 2 != 0) {
        return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k; // handle negative values
        freq[r]++;
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue; // already handled when k is even
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false;
    int[] count = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += k;
        count[rem]++;
    }
    // Count of remainder 0 must be even
    if (count[0] % 2 != 0) return false;
    // For each remainder r, count[r] must equal count[k - r]
    for (int r = 1; r <= k / 2; r++) {
        int complement = k - r;
        if (r == complement) {
            // Special case for remainder k/2 when k is even
            if (count[r] % 2 != 0) return false;
        } else {
            if (count[r] != count[complement]) return false;
        }
    }
    return true;
}

