    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        int childTime = dfs(nei, node, graph, hasApple);
        if (childTime > 0 || hasApple[nei]) {
            time += childTime + 2;
        }
    }
    return time;
}

