public String sortString(String s) {
    int[] freq = new int[65536];
    int total = s.length();
    for (int i = 0; i < total; i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder result = new StringBuilder(total);

    while (total > 0) {
        // Ascending part
        int last = -1;
        // Pick the smallest character
        for (int i = 0; i < freq.length; i++) {
            if (freq[i] > 0) {
                last = i;
                result.append((char) last);
                freq[last]--;
                total--;
                break;
            }
        }
        // Continue picking smallest characters greater than last
        while (true) {
            int next = -1;
            for (int i = last + 1; i < freq.length; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) break;
            last = next;
            result.append((char) last);
            freq[last]--;
            total--;
        }

        if (total == 0) break;

        // Descending part
        // Pick the largest character
        for (int i = freq.length - 1; i >= 0; i--) {
            if (freq[i] > 0) {
                last = i;
                result.append((char) last);
                freq[last]--;
                total--;
                break;
            }
        }
        // Continue picking largest characters smaller than last
        while (true) {
            int next = -1;
            for (int i = last - 1; i >= 0; i--) {
