        // Ascending phase
        java.util.Map.Entry<Character, Integer> entry = map.firstEntry();
        char last = entry.getKey();
        result.append(last);
        if (--entry.getValue() == 0) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue());
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> next = map.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            result.append(last);
            if (--next.getValue() == 0) {
                map.remove(last);
            } else {
                map.put(last, next.getValue());
            }
        }

        // Descending phase
        if (map.isEmpty()) break;
        entry = map.lastEntry();
        last = entry.getKey();
        result.append(last);
        if (--entry.getValue() == 0) {
            map.remove(last);
        } else {
            map.put(last, entry.getValue());
        }
        while (true) {
            java.util.Map.Entry<Character, Integer> prev = map.lowerEntry(last);
            if (prev == null) break;
            last = prev.getKey();
            result.append(last);
            if (--prev.getValue() == 0) {
                map.remove(last);
            } else {
                map.put(last, prev.getValue());
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[256];
    int total = s.length();
    for (char c : s.toCharArray()) {
        freq[c]++;
    }
    StringBuilder result = new StringBuilder(total);
    while (total > 0) {
        // Ascending part
        int i = 0;
        for (; i < 256; i++) {
            if (freq[i] > 0) {
                break;
            }
        }
        if (i == 256) {
            break;
        }
        result.append((char) i);
        freq[i]--;
        total--;
        int last = i;
        while (true) {
            int next = -1;
            for (int j = last + 1; j < 256; j++) {
                if (freq[j] > 0) {
                    next = j;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            total--;
            last = next;
        }
        if (total == 0) {
            break;
        }
        // Descending part
        int k = 255;
        for (; k >= 0; k--) {
            if (freq[k] > 0) {
                break;
            }
        }
        if (k < 0) {
            break;
        }
        result.append((char) k);
        freq[k]--;
        total--;
        last = k;
        while (true) {
            int next = -1;
            for (int l = last - 1; l >= 0; l--) {
                if (freq[l] > 0) {
                    next = l;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            total--;
            last = next;
        }
    }
    return result.toString();
}

