public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int cur = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = cur;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0; // can start at step 1 without paying
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costOneStep = dp[i - 1] + cost[i - 1];
        int costTwoStep = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costOneStep, costTwoStep);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int oneStepBefore = 0; // cost to reach step 0
    int twoStepsBefore = 0; // cost to reach step -1 (treated as 0)
    int current = 0;
    for (int i = 2; i <= n; i++) {
        current = Math.min(oneStepBefore + cost[i - 1], twoStepsBefore + cost[i - 2]);
        twoStepsBefore = oneStepBefore;
        oneStepBefore = current;
    }
    return current;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prevPrev = 0; // dp[i-2]
    int prev = 0;     // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int stepPrev = cost[i - 1];
        int stepPrevPrev = cost[i - 2];
        int curr = Math.min(prev + stepPrev, prevPrev + stepPrevPrev);
        prevPrev = prev;
        prev = curr;
    }
    return prev;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0 || n == 1) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp[i - 1] + cost[i - 1];
        int costFromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

