public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;            // total possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;           // to keep only k bits
    int val = 0;
    // Build the value for the first window of length k
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen[val] = true;
    int count = 1;
    // Slide the window across the string
    for (int i = k; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            if (++count == total) return true;  // all codes found
        }
    }
    return false;  // not all codes occurred
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true;
    int n = s.length();
    if (n < k) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int cur = 0;
    int mask = total - 1;
    for (int i = 0; i < k - 1; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    for (int i = k - 1; i < n; i++) {
        cur = ((cur << 1) | (s.charAt(i) - '0')) & mask;
        seen[cur] = true;
    }
    for (boolean b : seen) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) return true; // Trivially true for empty pattern
    int totalCodes = 1 << k;
    if (s.length() < k) return false;

    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1; // Keeps only k bits
    int current = 0;

    // Build the first k-bit number
    for (int i = 0; i < k; i++) {
        current = (current << 1) | (s.charAt(i) - '0');
    }
    seen[current] = true;
    int count = 1;

    // Slide over the string
    for (int i = k; i < s.length(); i++) {
        current = ((current << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[current]) {
            seen[current] = true;
            count++;
            if (count == totalCodes) return true; // Early exit
        }
    }
    return count == totalCodes;
}

