public int minInsertions(String s) {
    int needLeft = 0;
    int needRight = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            needRight++;
        } else { // c == ')'
            if (needRight > 0) {
                needRight--;
            } else {
                needLeft++;
            }
        }
    }
    return needLeft + needRight;
}

public int minInsertions(String s) {
    int insertions = 0;
