    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            left++;
        } else { // ')'
            if (left == 0) {
                insertions++; // need a '(' before this ')'
            } else {
                left--;
            }
        }
    }
    return insertions + left;
}

