}

public int minInsertions(String s) {
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed for unmatched ')'
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            balance--;
            if (balance < 0) {
                // We have an unmatched ')', need to insert a '(' before it
                insertions++;
                balance = 0;
            }
        }
    }
    // Any remaining unmatched '(' need a ')' each
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    long sq = 1L * n * n;
    if (n % 2 == 0) {
        return (int) (sq / 4);
    } else {
        return (int) ((sq - 1) / 4);
    }
}

public int minOperations(int n) {
    int lowerCount = n / 2;
    return lowerCount * (n - lowerCount);
}

public int minOperations(int n) {
    long start = (n + 1L) / 2;            // first index with positive diff
    long count = n - start;               // number of such indices
    if (count == 0) return 0;
    long sumIndices = (start + (n - 1L)) * count / 2; // sum of i from start to n-1
    long result = 2 * sumIndices - (n - 1L) * count;   // total positive diff
    return (int) result;
}

public int minOperations(int n) {
    if (n % 2 == 0) {
        int p = n / 2;
        return p * p;
    } else {
        int p = (n - 1) / 2;
        return p * (p + 1);
    }
}

