public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1); // F1
    fibs.add(1); // F2
    while (true) {
        int size = fibs.size();
        int next = fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // Greedy selection from largest to smallest
    int remaining = k;
    int count = 0;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        if (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

