public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers up to k
    int[] fib = new int[50]; // 50 is more than enough for int range
    fib[0] = 1;
    fib[1] = 1;
    int m = 2;
    while (true) {
        long next = (long)fib[m-1] + (long)fib[m-2];
        if (next > k || next > Integer.MAX_VALUE) break;
        fib[m] = (int) next;
        m++;
    }
    // Greedy subtraction from largest to smallest
    int count = 0;
    for (int i = m - 1; i >= 0 && k > 0; i--) {
        if (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    java.util.List<Integer> bigFactors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int paired = n / i;
            if (paired != i) {
                bigFactors.add(paired);
            }
        }
    }
    for (int i = bigFactors.size() - 1; i >= 0; i--) {
        factors.add(bigFactors.get(i));
    }
    return k > factors.size() ? -1 : factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; (long)i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int smallSize = small.size();
    if (k <= smallSize) {
        return small.get(k - 1);
    }
    int remaining = k - smallSize;
    if (remaining <= large.size()) {
        return large.get(large.size() - remaining);
    }
    return -1;
}

