public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i);
            }
        }
    }
    java.util.Collections.sort(large);
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - 1 - small.size());
    }
}

public String makeGood(String s) {
    char[] stack = new char[s.length()];
    int top = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (top > 0 && Math.abs(c - stack[top - 1]) == 32) {
            top--;
        } else {
            stack[top++] = c;
        }
    }
    return new String(stack, 0, top);
}

public String makeGood(String s) {
    StringBuilder sb = new StringBuilder();
    for (char c : s.toCharArray()) {
        int len = sb.length();
        if (len > 0) {
