public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append('a');
    }
    int remaining = k - n; // extra value needed
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // maximum we can add to this character
        sb.setCharAt(i, (char) ('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    char[] arr = new char[n];
    Arrays.fill(arr, 'a'); // start with all 'a's, sum = n
    int remaining = k - n; // amount to distribute as increments

    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each char can increase up to 25 ('z' - 'a')
        arr[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(arr);
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = n - 1; i >= 0; i--) {
        int maxVal = Math.min(26, k - i); // maximum value allowed at this position
        sb.append((char) ('a' + maxVal - 1));
        k -= maxVal;
    }
    return sb.reverse().toString();
}

