public static int singleNumber(int[] nums) {
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (bitCount[i] % 3 != 0) {
            result |= 1 << i;
        }
    }
    return result;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

