public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n - (n / factor) * factor;
        long cur = (n / factor) % 10;
        long high = n / (factor * 10);
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + lower + 1;
        } else {
            count += (high + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

