    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int r = 0, c = 0;
    boolean up = true;
    for (int i = 0; i < m * n; i++) {
        result[i] = mat[r][c];
        if (up) {
            if (c == n - 1) {      // hit right boundary, move down
                r++;
                up = false;
            } else if (r == 0) {   // hit top boundary, move right
                c++;
                up = false;
            } else {               // move diagonally up-right
                r--;
                c++;
            }
        } else {
            if (r == m - 1) {      // hit bottom boundary, move right
                c++;
                up = true;
            } else if (c == 0) {   // hit left boundary, move down
                r++;
                up = true;
            } else {               // move diagonally down-left
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
