    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1; // already the highest permutation
    }
    // Find rightmost successor to pivot in suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    // Swap pivot with successor
    int temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Reverse suffix
    int left = i + 1, right = len - 1;
    while (left < right) {
        int t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    // Convert back to integer
    int result = 0;
    for (int d : digits) {
        result = result * 10 + d;
    }
    return result;
}

