private static List<String> buildStrobogrammatic(int currLen, int totalLen) {
    List<String> list = new ArrayList<>();
    if (currLen == 0) {
        list.add("");
        return list;
    }
    if (currLen == 1) {
        list.add("0");
        list.add("1");
        list.add("8");
        return list;
    }

    List<String> subList = buildStrobogrammatic(currLen - 2, totalLen);
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };

    for (String sub : subList) {
        for (char[] pair : pairs) {
            // Avoid leading zeros
            if (currLen == totalLen && pair[0] == '0') {
                continue;
            }
            StringBuilder sb = new StringBuilder();
            sb.append(pair[0]);
            sb.append(sub);
            sb.append(pair[1]);
            list.add(sb.toString());
        }
    }
    return list;
}

