public static List<String> find(int curLen, int targetLen, String cur) {
    if (cur.length() == targetLen) {
        // For targetLen==0 only one case: empty string? But we can handle...
        if (targetLen == 0) return new ArrayList<>();
        // Actually base case when cur.length() == targetLen, return list of cur
        List<String> res = new ArrayList<>();
        res.add(cur);
        return res;
    }

    List<String> res = new ArrayList<>();
    // If cur length == 0 and targetLen >1, cannot add zero at outermost 0-digit pair
    String[][] pairs = {{"0","0"},{"1","1"},{"6","9"},{"8","8"},{"9","6"}};
    for (String[] p : pairs) {
        // avoid leading zero
        if (cur.length() == 0 && targetLen > 1 && p[0].equals("0")) continue;
        // if this will lead to final length equals targetLen and only middle if targetLen is odd and cur length== targetLen-1???
        if (cur.length() + 2 > targetLen) continue; // we can't exceed
        String added = p[0] + cur + p[1];
        res.addAll(find(targetLen - added.length(), targetLen, added)); // Actually recursion currently uses cur string; but easier to maintain only building until length targetLen
    }
    return res;
}

