private List<String> helper(int currentLen, int totalLen){
    if (currentLen == 0) return new ArrayList<>(Arrays.asList(""));
    if (currentLen == 1) return new ArrayList<>(Arrays.asList("0","1","8"));
    List<String> sub = helper(currentLen - 2, totalLen);
    List<String> result = new ArrayList<>();
