public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int curr = 1;
    while (result.size() < n) {
        result.add(curr);
        if ((long)curr * 10 <= n) {
            curr *= 10;
        } else if (curr % 10 != 9 && curr + 1 <= n) {
            curr++;
        } else {
            while (curr % 10 == 9) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            dfs(i, n, result);
        }
        return result;
    }

private static void dfs(int cur, int n, List<Integer> result) {
        if (cur > n) {
            return;
        }
        result.add(cur);
        for (int i = 0; i < 10; i++) {
            long next = (long) cur * 10 + i;
            if (next > n) {
                break;
            }
            dfs((int) next, n, result);
        }
    }

